function Log($msg) {
    $lstLog.Items.Add($msg) | Out-Null
    $lstLog.TopIndex = $lstLog.Items.Count - 1
    [System.Windows.Forms.Application]::DoEvents()
}

$script:packs = @()
$script:selectedPack = $null
$script:selectedTarget = $null
$script:launcherTiles = @()

function Set-ChosenTarget([string]$path) {
    $script:selectedTarget = $path
    $txtChosen.Text = $path
    $btnUpdate.Enabled = $true
}

function Make-LauncherTile($logoImg, $label, $finder) {
    $tile = New-Object System.Windows.Forms.Panel
    $tile.Size = New-Object System.Drawing.Size((Sz 130),(Sz 90))
    $tile.BackColor = [System.Drawing.Color]::FromArgb(40,40,45)
    $tile.Margin = New-Object System.Windows.Forms.Padding((Sz 6))
    $tile.Cursor = [System.Windows.Forms.Cursors]::Hand

    $pic = New-Object System.Windows.Forms.PictureBox
    $pic.Image = $logoImg
    $pic.SizeMode = "Zoom"
    $pic.Location = New-Object System.Drawing.Point((Sz 33),(Sz 8))
    $pic.Size = New-Object System.Drawing.Size((Sz 64),(Sz 46))
    $pic.BackColor = [System.Drawing.Color]::Transparent
    $tile.Controls.Add($pic)

    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Text = $label
    $lbl.ForeColor = [System.Drawing.Color]::White
    $lbl.Font = New-Object System.Drawing.Font("Segoe UI", 8, [System.Drawing.FontStyle]::Bold)
    $lbl.TextAlign = "MiddleCenter"
    $lbl.Location = New-Object System.Drawing.Point(0,(Sz 58))
    $lbl.Size = New-Object System.Drawing.Size((Sz 130),(Sz 20))
    $tile.Controls.Add($lbl)

    $clickHandler = {
        if (-not $script:selectedPack) {
            [System.Windows.Forms.MessageBox]::Show("Once bir mod paketi sec.", "AnuDownloader") | Out-Null
            return
        }
        foreach ($t in $script:launcherTiles) { $t.BackColor = [System.Drawing.Color]::FromArgb(40,40,45) }
        $tile.BackColor = [System.Drawing.Color]::FromArgb(60,90,60)
        $found = & $finder $script:selectedPack.folder_name
        if ($found) {
            Set-ChosenTarget $found
        } else {
            $r = [System.Windows.Forms.MessageBox]::Show("$label icin otomatik klasor bulunamadi.`nManuel secmek ister misin?", "AnuDownloader", "YesNo")
            if ($r -eq "Yes") {
                $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
                $dlg.Description = "$($script:selectedPack.name) icin $label mods klasorunu sec"
                if ($dlg.ShowDialog() -eq "OK") { Set-ChosenTarget $dlg.SelectedPath }
            }
        }
    }.GetNewClosure()
    $tile.Add_Click($clickHandler)
    $pic.Add_Click($clickHandler)
    $lbl.Add_Click($clickHandler)

    $script:launcherTiles += $tile
    return $tile
}

$panelLaunchers.Controls.Add((Make-LauncherTile $MRLogoImg "Modrinth" ${function:Find-ModrinthTarget}))
$panelLaunchers.Controls.Add((Make-LauncherTile $CFLogoImg "CurseForge" ${function:Find-CurseForgeTarget}))
$panelLaunchers.Controls.Add((Make-LauncherTile $TLLogoImg "TLauncher" ${function:Find-TLauncherTarget}))

function Select-PackTile($tile, $pack) {
    foreach ($t in $panelPacks.Controls) {
        if ($t -is [System.Windows.Forms.Panel]) { $t.BackColor = [System.Drawing.Color]::FromArgb(40,40,45) }
    }
    $tile.BackColor = [System.Drawing.Color]::FromArgb(60,90,60)
    $script:selectedPack = $pack
    $script:selectedTarget = $null
    $txtChosen.Text = ""
    $btnUpdate.Enabled = $false
    foreach ($t in $script:launcherTiles) { $t.BackColor = [System.Drawing.Color]::FromArgb(40,40,45) }
}

Log "Paket listesi indiriliyor..."
try {
    $index = Invoke-RestMethod -Uri $IndexUrl -Headers @{ "Cache-Control" = "no-cache" }
    $script:packs = $index.packs
} catch {
    [System.Windows.Forms.MessageBox]::Show("Paket listesi indirilemedi:`n$($_.Exception.Message)", "AnuDownloader") | Out-Null
}

foreach ($pack in $script:packs) {
    $tile = New-Object System.Windows.Forms.Panel
    $tile.Size = New-Object System.Drawing.Size((Sz 148),(Sz 138))
    $tile.BackColor = [System.Drawing.Color]::FromArgb(40,40,45)
    $tile.Margin = New-Object System.Windows.Forms.Padding((Sz 6))
    $tile.Cursor = [System.Windows.Forms.Cursors]::Hand

    $pic = New-Object System.Windows.Forms.PictureBox
    $pic.Size = New-Object System.Drawing.Size((Sz 128),(Sz 96))
    $pic.Location = New-Object System.Drawing.Point((Sz 10),(Sz 8))
    $pic.SizeMode = "Zoom"
    $pic.BackColor = [System.Drawing.Color]::FromArgb(60,60,65)
    $img = Get-CachedImage $pack.banner_url
    if ($img) { $pic.Image = $img }
    $tile.Controls.Add($pic)

    $lblName = New-Object System.Windows.Forms.Label
    $lblName.Text = $pack.name
    $lblName.ForeColor = [System.Drawing.Color]::White
    $lblName.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $lblName.Location = New-Object System.Drawing.Point((Sz 10),(Sz 108))
    $lblName.Size = New-Object System.Drawing.Size((Sz 128),(Sz 26))
    $tile.Controls.Add($lblName)

    $clickHandler = { Select-PackTile $tile $pack }.GetNewClosure()
    $tile.Add_Click($clickHandler)
    $pic.Add_Click($clickHandler)
    $lblName.Add_Click($clickHandler)

    $panelPacks.Controls.Add($tile)
}

$btnUpdate.Add_Click({
    $lstLog.Items.Clear()
    $progress.Value = 0

    if (-not $script:selectedPack) {
        [System.Windows.Forms.MessageBox]::Show("Once bir mod paketi sec.", "AnuDownloader") | Out-Null
        return
    }
    if (-not $script:selectedTarget) {
        [System.Windows.Forms.MessageBox]::Show("Once bir launcher logosuna tikla (kurulum hedefi sec).", "AnuDownloader") | Out-Null
        return
    }
    $modsFolder = $script:selectedTarget
    if (-not (Test-Path $modsFolder)) {
        New-Item -ItemType Directory -Path $modsFolder -Force | Out-Null
    }

    Log "Manifest indiriliyor: $($script:selectedPack.name)"
    try {
        $manifest = Invoke-RestMethod -Uri $script:selectedPack.manifest_url -Headers @{ "Cache-Control" = "no-cache" }
    } catch {
        Log "HATA: Manifest indirilemedi - $($_.Exception.Message)"
        return
    }
    Log "Dosya sayisi: $($manifest.files.Count)"

    $toDownload = @()
    foreach ($f in $manifest.files) {
        $localPath = Join-Path $modsFolder $f.filename
        if (-not (Test-Path -LiteralPath $localPath)) {
            $toDownload += $f; continue
        }
        if ((Get-FileSha256 $localPath) -ne $f.sha256) { $toDownload += $f }
    }

    $manifestNames = $manifest.files | ForEach-Object { $_.filename }
    $localJars = Get-ChildItem -Path $modsFolder -Filter *.jar -File -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }
    $extra = $localJars | Where-Object { $manifestNames -notcontains $_ }

    if ($toDownload.Count -eq 0) {
        Log "Her sey guncel."
    } else {
        Log "$($toDownload.Count) dosya indirilecek."
        $progress.Maximum = $toDownload.Count
        $i = 0
        foreach ($f in $toDownload) {
            $i++
            $dest = Join-Path $modsFolder $f.filename
            Log "[$i/$($toDownload.Count)] $($f.filename)"
            try {
                Invoke-WebRequest -Uri $f.url -OutFile $dest -UseBasicParsing
                $progress.Value = $i
            } catch {
                Log "  HATA: $($_.Exception.Message)"
            }
        }
        Log "Guncelleme tamamlandi."
    }

    if ($extra.Count -gt 0) {
        Log "Not: pakette olmayan $($extra.Count) ekstra dosya var (dokunulmadi)."
    }

    $cfg.targets | Add-Member -NotePropertyName $script:selectedPack.id -NotePropertyValue $modsFolder -Force
    Save-Config $cfg
    [System.Windows.Forms.MessageBox]::Show("Islem bitti.", "AnuDownloader") | Out-Null
})

[void]$form.ShowDialog()
